using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;
public static class SkillSpriteFolderSync {
 public sealed class Image {public Sprite sprite;public string identity,name;}
 public static string Identity(Sprite sprite){return sprite!=null&&AssetDatabase.TryGetGUIDAndLocalFileIdentifier(sprite,out string guid,out long local)?guid+":"+local:null;}
 public static string Folder(TrainingMoveData asset)=>Path.GetDirectoryName(AssetDatabase.GetAssetPath(asset)).Replace((char)92,'/')+"/Sprite";
 public static List<Image> Detect(TrainingMoveData asset){string folder=Folder(asset);if(AssetDatabase.IsValidFolder(folder+"s"))throw new InvalidOperationException("Legacy Sprites folder found: migrate it; never read both folders");var images=new List<Image>();if(!AssetDatabase.IsValidFolder(folder))return images;var ids=new HashSet<string>();foreach(string guid in AssetDatabase.FindAssets("t:Texture2D",new[]{folder})){string path=AssetDatabase.GUIDToAssetPath(guid);foreach(var sprite in AssetDatabase.LoadAllAssetsAtPath(path).OfType<Sprite>()){string id=Identity(sprite);if(id!=null&&ids.Add(id))images.Add(new Image{sprite=sprite,identity=id,name=path.Substring(folder.Length+1)+" / "+sprite.name});}}images.Sort((a,b)=>{int n=EditorUtility.NaturalCompare(a.name,b.name);return n!=0?n:string.CompareOrdinal(a.identity,b.identity);});return images;}
 static string Key(TrainingSpriteFrame f)=>f==null?null:Identity(f.sprite)??f.sourceIdentity;
 public static string Changes(TrainingMoveData saved,List<Image> images){var prior=saved.data.spriteSequence?.frames??new TrainingSpriteFrame[0];var ids=new HashSet<string>(images.Select(x=>x.identity));var old=new HashSet<string>(prior.Select(Key).Where(x=>!string.IsNullOrEmpty(x)));int added=images.Count(x=>!old.Contains(x.identity)),removed=old.Count(x=>!ids.Contains(x)),renamed=prior.Count(f=>f!=null&&!string.IsNullOrEmpty(f.sourceName)&&images.Any(x=>x.identity==Key(f)&&x.name!=f.sourceName));bool order=!prior.Select(Key).SequenceEqual(images.Select(x=>x.identity));return images.Count+" detected | +"+added+" / -"+removed+" / renamed "+renamed+" | order "+(order?"changed":"same");}
 public static void Sync(TrainingMoveData asset,TrainingMoveData draft){if(draft==null||draft==asset||EditorUtility.IsPersistent(draft))throw new ArgumentException("Sync requires a private unsaved draft");Undo.RecordObject(draft,"Sync detected skill sprites");var images=Detect(asset);var seq=draft.data.spriteSequence??new TrainingSpriteSequence();var holds=new Dictionary<string,int>();foreach(var h in seq.rememberedHolds??new TrainingSpriteHold[0])if(h!=null&&!string.IsNullOrEmpty(h.identity)&&h.holdFrames>0)holds[h.identity]=h.holdFrames;foreach(var f in seq.frames??new TrainingSpriteFrame[0]){string id=Key(f);if(string.IsNullOrEmpty(id))continue;if(f.holdFrames<1||f.holdFrames>36000)throw new ArgumentException("Correct invalid holds before syncing");holds[id]=f.holdFrames;}if(holds.Count+images.Count>8192)throw new ArgumentException("Hold history capacity exceeded");seq.frames=images.Select(x=>new TrainingSpriteFrame{sprite=x.sprite,sourceIdentity=x.identity,sourceName=x.name,holdFrames=holds.TryGetValue(x.identity,out var value)?value:1}).ToArray();foreach(var f in seq.frames)holds[f.sourceIdentity]=f.holdFrames;seq.rememberedHolds=holds.OrderBy(x=>x.Key,StringComparer.Ordinal).Select(x=>new TrainingSpriteHold{identity=x.Key,holdFrames=x.Value}).ToArray();if(!seq.Validate(out var error))throw new ArgumentException(error);draft.data.spriteSequence=seq;}
 public static bool ValidateSelection(TrainingMoveData asset,TrainingMoveData draft,out string error){error="";var seq=draft.data.spriteSequence;if(seq==null||seq.frames==null||seq.frames.Length==0)return true;var images=Detect(asset);if(!seq.frames.Select(Key).SequenceEqual(images.Select(x=>x.identity))||seq.frames.Any(f=>f==null||f.sprite==null||f.sourceIdentity!=Identity(f.sprite)||!images.Any(x=>x.identity==f.sourceIdentity&&x.name==f.sourceName))){error="Detected folder differs: Sync to draft before saving";return false;}return seq.Validate(out error);}
}
